svg.script:

const svgNS = "http://www.w3.org/2000/svg";
const xlinkNS = "http://www.w3.org/1999/xlink";
const targetLayer = document.getElementById("target-layer");
const agentLayer = document.getElementById("agent-layer");
const salvoLayer = document.getElementById("salvo-layer");

const AGENT_COUNT = 100;
const TARGET_COUNT = 20;

const targets = [];
const agents = [];
const salvos = [];
const agentsMap = {};

let score = 0;
let destroyedCount = 0;
let wave = 1;
let frameCount = 0;

function initTargets() {
  for(let i=0; i<TARGET_COUNT; i++) {
    let colorClass = i < 7 ? "bolt-red" : (i < 14 ? "bolt-green" : "bolt-blue");
    let t = {
      id: i,
      x: 80 + Math.random() * 480,
      y: 60 + Math.random() * 220,
      vx: (Math.random() - 0.5) * 1.5,
      vy: (Math.random() - 0.5) * 0.8,
      scale: 1.2 + Math.random() * 0.8,
      colorClass: colorClass,
      health: 100,
      alive: true,
      el: null,
      animEl: null,
      healthEl: null
    };

    let wrapperG = document.createElementNS(svgNS, "g");
    let animG = document.createElementNS(svgNS, "g");
    animG.setAttribute("class", "float1");
    animG.style.animationDelay = (Math.random() * -9) + "s";

    let use = document.createElementNS(svgNS, "use");
    use.setAttributeNS(xlinkNS, "href", "#fire-grin");
    use.setAttribute("href", "#fire-grin");
    animG.appendChild(use);

    let tint = document.createElementNS(svgNS, "circle");
    tint.setAttribute("cx", "0"); tint.setAttribute("cy", "0"); tint.setAttribute("r", "25");
    tint.setAttribute("fill", colorClass === "bolt-red" ? "rgba(255,0,0,0.15)" : (colorClass === "bolt-green" ? "rgba(0,255,0,0.15)" : "rgba(0,100,255,0.15)"));
    tint.setAttribute("filter", "url(#bolt-glow)");
    animG.appendChild(tint);

    wrapperG.appendChild(animG);

    let hBg = document.createElementNS(svgNS, "rect");
    hBg.setAttribute("x", "-15"); hBg.setAttribute("y", "30"); hBg.setAttribute("width", "30"); hBg.setAttribute("height", "4"); hBg.setAttribute("fill", "#333");
    wrapperG.appendChild(hBg);

    let hBar = document.createElementNS(svgNS, "rect");
    hBar.setAttribute("x", "-15"); hBar.setAttribute("y", "30"); hBar.setAttribute("width", "30"); hBar.setAttribute("height", "4"); hBar.setAttribute("fill", "#0f0");
    hBar.setAttribute("id", "health-"+i);
    wrapperG.appendChild(hBar);

    targetLayer.appendChild(wrapperG);

    wrapperG.setAttribute("class", "target-entity");
    wrapperG.addEventListener("click", () => {
      if(t.alive) {
        t.health -= 25;
        if(t.health <= 0) destroyTarget(t.id);

        let flash = document.createElementNS(svgNS, "circle");
        flash.setAttribute("cx", "0"); flash.setAttribute("cy", "0"); flash.setAttribute("r", "30"); flash.setAttribute("fill", "#fff"); flash.setAttribute("opacity", "0.8");
        animG.appendChild(flash);
        let animOp = document.createElementNS(svgNS, "animate");
        animOp.setAttribute("attributeName", "opacity"); animOp.setAttribute("from", "0.8"); animOp.setAttribute("to", "0"); animOp.setAttribute("dur", "0.3s"); animOp.setAttribute("fill", "freeze");
        flash.appendChild(animOp);
        setTimeout(() => flash.remove(), 400);
      }
    });

    t.el = wrapperG;
    t.animEl = animG;
    t.healthEl = hBar;
    targets.push(t);
  }
}

function initAgents() {
  for(let i=0; i<AGENT_COUNT; i++) {
    let y = 360 + Math.random() * 190;
    let x = Math.random() * 580;
    let scale = 0.25 + ((y - 360) / 190) * 0.35;
    let walkerClass = ["m1", "m2", "m3"][Math.floor(Math.random()*3)];
    let targetId = i % TARGET_COUNT;
    let colorClass = targets[targetId].colorClass;

    let a = { id: i, x, y, scale, walkerClass, targetId, colorClass, el: null, animEl: null };

    let wrapperG = document.createElementNS(svgNS, "g");
    let animG = document.createElementNS(svgNS, "g");
    animG.setAttribute("class", walkerClass);
    animG.style.animationDelay = (Math.random() * -8) + "s";

    let use = document.createElementNS(svgNS, "use");
    use.setAttributeNS(xlinkNS, "href", "#walker-beam");
    use.setAttribute("href", "#walker-beam");
    use.setAttribute("x", "0"); use.setAttribute("y", "-80"); // Shift so feet are at local 0
    animG.appendChild(use);

    wrapperG.appendChild(animG);
    agents.push(a);

    a.el = wrapperG;
    a.animEl = animG;
    agentsMap[a.id] = a;
  }
  agents.sort((a, b) => a.y - b.y);
  agents.forEach(a => agentLayer.appendChild(a.el));
}

function initSalvos() {
  for(let i=0; i<AGENT_COUNT; i++) {
    let a = agents[i];
    let s = { agentId: a.id, targetId: a.targetId, colorClass: a.colorClass, el: null };

    let line = document.createElementNS(svgNS, "line");
    line.setAttribute("class", a.colorClass);
    line.setAttribute("stroke-width", "2");
    line.setAttribute("filter", "url(#bolt-glow)");

    salvoLayer.appendChild(line);
    s.el = line;
    salvos.push(s);
  }
}

function destroyTarget(id) {
  let t = targets[id];
  if(!t.alive) return;

  t.alive = false; t.health = 0;
  t.el.setAttribute("visibility", "hidden");
  score += 100; destroyedCount++;

  let gExp = document.createElementNS(svgNS, "g");
  gExp.setAttribute("transform", `translate(${t.x}, ${t.y}) scale(${t.scale})`);
  targetLayer.appendChild(gExp);

  let c1 = document.createElementNS(svgNS, "circle");
  c1.setAttribute("r", "10"); c1.setAttribute("fill", "#fff"); c1.setAttribute("filter", "url(#explode-glow)");
  gExp.appendChild(c1);
  let animR = document.createElementNS(svgNS, "animate"); animR.setAttribute("attributeName", "r"); animR.setAttribute("from", "10"); animR.setAttribute("to", "60"); animR.setAttribute("dur", "0.6s"); animR.setAttribute("fill", "freeze"); c1.appendChild(animR);
  let animOp = document.createElementNS(svgNS, "animate"); animOp.setAttribute("attributeName", "opacity"); animOp.setAttribute("from", "1"); animOp.setAttribute("to", "0"); animOp.setAttribute("dur", "0.6s"); animOp.setAttribute("fill", "freeze"); c1.appendChild(animOp);

  let c2 = document.createElementNS(svgNS, "circle");
  c2.setAttribute("r", "5"); c2.setAttribute("fill", "none"); c2.setAttribute("stroke", t.colorClass === "bolt-red" ? "#cc0000" : (t.colorClass === "bolt-green" ? "#00ff00" : "#0088ff")); c2.setAttribute("stroke-width", "4");
  gExp.appendChild(c2);
  let animR2 = document.createElementNS(svgNS, "animate"); animR2.setAttribute("attributeName", "r"); animR2.setAttribute("from", "5"); animR2.setAttribute("to", "80"); animR2.setAttribute("dur", "0.8s"); animR2.setAttribute("fill", "freeze"); c2.appendChild(animR2);
  let animOp2 = document.createElementNS(svgNS, "animate"); animOp2.setAttribute("attributeName", "opacity"); animOp2.setAttribute("from", "1"); animOp2.setAttribute("to", "0"); animOp2.setAttribute("dur", "0.8s"); animOp2.setAttribute("fill", "freeze"); c2.appendChild(animOp2);

  setTimeout(() => gExp.remove(), 1000);

  salvos.forEach(s => {
    if(s.targetId === id) {
      let newTarget = findClosestAliveTarget(s.agentId);
      if(newTarget) {
        s.targetId = newTarget.id; s.colorClass = newTarget.colorClass;
        s.el.setAttribute("class", newTarget.colorClass);
        agentsMap[s.agentId].targetId = newTarget.id; agentsMap[s.agentId].colorClass = newTarget.colorClass;
      } else {
        s.el.setAttribute("visibility", "hidden"); agentsMap[s.agentId].targetId = -1;
      }
    }
  });

  updateHUD();
  if(destroyedCount >= TARGET_COUNT) { wave++; setTimeout(respawnTargets, 3000); }
}

function findClosestAliveTarget(agentId) {
  let agent = agentsMap[agentId];
  let closest = null, minDist = Infinity;
  targets.forEach(t => {
    if(t.alive) { let dx = t.x - agent.x; let dy = t.y - agent.y; let dist = Math.sqrt(dx*dx + dy*dy); if(dist < minDist) { minDist = dist; closest = t; } }
  });
  return closest;
}

function respawnTargets() {
  destroyedCount = 0; score += 500;
  targets.forEach(t => {
    t.alive = true; t.health = 100;
    t.x = 80 + Math.random() * 480; t.y = 60 + Math.random() * 220;
    t.vx = (Math.random() - 0.5) * 1.5; t.vy = (Math.random() - 0.5) * 0.8;
    t.el.setAttribute("visibility", "visible");
    t.healthEl.setAttribute("width", "30"); t.healthEl.setAttribute("fill", "#0f0");
  });
  salvos.forEach(s => {
    let tId = s.agentId % TARGET_COUNT;
    s.targetId = tId; s.colorClass = targets[tId].colorClass;
    s.el.setAttribute("class", targets[tId].colorClass); s.el.setAttribute("visibility", "visible");
    agentsMap[s.agentId].targetId = tId; agentsMap[s.agentId].colorClass = targets[tId].colorClass;
  });
  updateHUD();
}

function updateHUD() {
  let rCount = 0, gCount = 0, bCount = 0;
  salvos.forEach(s => { if(s.colorClass === "bolt-red") rCount++; else if(s.colorClass === "bolt-green") gCount++; else if(s.colorClass === "bolt-blue") bCount++; });
  document.getElementById("hud-score").textContent = "SCORE: " + score;
  document.getElementById("hud-targets").textContent = "TARGETS: " + (TARGET_COUNT - destroyedCount) + " / " + TARGET_COUNT;
  document.getElementById("hud-agents").textContent = "AGENTS: " + AGENT_COUNT;
  document.getElementById("hud-bolts").textContent = "RED: " + rCount;
  document.getElementById("hud-bolts2").textContent = "GREEN: " + gCount;
  document.getElementById("hud-bolts3").textContent = "BLUE: " + bCount;
  document.getElementById("hud-wave").textContent = "WAVE: " + wave;
}

function gameLoop() {
  frameCount++;
  targets.forEach(t => {
    if(!t.alive) return;
    t.x += t.vx; t.y += t.vy + Math.sin(frameCount * 0.05 + t.id) * 0.5;
    if(t.x < 50 || t.x > 550) t.vx *= -1;
    if(t.y < 40 || t.y > 280) t.vy *= -1;
    t.el.setAttribute("transform", `translate(${t.x}, ${t.y}) scale(${t.scale})`);

    let attackerCount = 0;
    salvos.forEach(s => { if(s.targetId === t.id) attackerCount++; });
    t.health -= attackerCount * 0.15;
    if(t.health <= 0) destroyTarget(t.id);

    let w = Math.max(0, t.health) * 0.3;
    t.healthEl.setAttribute("width", w);
    t.healthEl.setAttribute("fill", t.health > 50 ? "#0f0" : (t.health > 25 ? "#ff0" : "#f00"));
  });

  agents.forEach(a => {
    let target = targets[a.targetId];
    if(target && target.alive) { let dx = target.x - a.x; if(Math.abs(dx) > 10) a.x += dx * 0.02; }
    a.el.setAttribute("transform", `translate(${a.x}, ${a.y}) scale(${a.scale})`);
  });

  salvos.forEach(s => {
    let agent = agentsMap[s.agentId]; let target = targets[s.targetId];
    if(!agent || !target || !target.alive) { s.el.setAttribute("visibility", "hidden"); return; }
    s.el.setAttribute("visibility", "visible");
    s.el.setAttribute("x1", agent.x); s.el.setAttribute("y1", agent.y - 155 * agent.scale);
    s.el.setAttribute("x2", target.x); s.el.setAttribute("y2", target.y);
  });

  requestAnimationFrame(gameLoop);
}

initTargets(); initAgents(); initSalvos(); updateHUD(); gameLoop();
